<script module lang="ts">
/**
 * Loading indicator for work of unknown duration (`design/components/spinner.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/spinner.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { Icon, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/spinner.module.css'

export interface SpinnerProps {
  /**
   * Announced once, so screen reader users know something is loading.
   */
  label?: string
  size?: 'sm' | 'md' | 'lg'
}
</script>

<script lang="ts">
let { label: labelOwn = 'Loading', size = 'md' }: SpinnerProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn, size: size }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
</script>

{@render joined.start?.()
}{#if joined.shown
  }<span class={styles.spinner} data-size={size} role="status" data-member="spinner"
    ><span class={styles.glyph}><Icon name="loading" {size} /></span
    ><span class={styles.label}>{label}</span
  ></span
>{/if
}{@render joined.end?.()}
